void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class F>void rejects(F action,const char* message){bool rejected=false;try{action();}catch(const std::exception&){rejected=true;}require(rejected,message);}
void le(std::ostream& output,unsigned value,unsigned count){for(unsigned i=0;i<count;++i)output.put(static_cast<char>(value>>(8*i)));}
void wave(const std::filesystem::path& path,unsigned frames){std::ofstream output(path,std::ios::binary);output.write("RIFF",4);le(output,36+frames*4,4);output.write("WAVEfmt ",8);le(output,16,4);le(output,1,2);le(output,2,2);le(output,48000,4);le(output,192000,4);le(output,4,2);le(output,16,2);output.write("data",4);le(output,frames*4,4);for(unsigned i=0;i<frames;++i){le(output,static_cast<unsigned>(static_cast<short>(std::sin(i*6.283185307179586*440/48000)*9000)),2);le(output,static_cast<unsigned>(static_cast<short>(std::sin(i*6.283185307179586*660/48000)*6000)),2);}}
double signalError(const DecodedAudio& reference,const DecodedAudio& value){double signal=0,error=0;const auto count=std::min(reference.samples.size(),value.samples.size());for(std::size_t i=4096;i+4096<count;++i){signal+=reference.samples[i]*reference.samples[i];const auto delta=reference.samples[i]-value.samples[i];error+=delta*delta;}return 10*std::log10(signal/std::max(error,1e-20));}
std::filesystem::path exportAudio(const std::filesystem::path& root,const std::filesystem::path& source,const std::string& format){AssetTransferRequest request;request.operation=AssetTransferOperation::Export;request.source=source;request.formatId=format;request.staging=root/(format+"-staging");request.destination=root/(format+"-output");request.settings=nlohmann::json::object();auto report=prepareAssetTransfer(request,assetFormatRegistry(),{});require(!report.losses.empty(),"Compressed output must disclose perceptual losses");require(report.summary.contains("encoderDelay")&&report.summary.contains("encoderPadding"),"Encoder delay and padding must be observable");return publishAssetTransfer(report);}
nlohmann::json apply(EditorSession& session,const std::string& operation,nlohmann::json values=nlohmann::json::object()){auto result=session.edit(operation,std::move(values));if(!result)throw std::runtime_error(operation+": "+result.diagnostics.dump());return result.value;}
nlohmann::json wait(EditorSession& session,const std::string& identity){const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(20);while(std::chrono::steady_clock::now()<deadline){session.pollTasks();for(const auto& row:session.tasks().report())if(row.at("id")==identity&&row.at("state")!="running")return row;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Compressed authoring task exceeded deadline");}

